mapper.select:
SELECT  FROM BSYPROG PROG WHERE PROG.DEL_YN='N'
AND (UPPER(PROG.PROGRAM_ID) LIKE CONCAT('%',UPPER(#{KEYWORD}),'%') OR UPPER(PROG.PROGRAM_KEY) LIKE CONCAT('%',UPPER(#{KEYWORD}),'%') OR UPPER(PROG.PROGRAM_NAME) LIKE CONCAT('%',UPPER(#{KEYWORD}),'%'))
AND PROG.MODULE_CODE=#{MODULE_CODE}
AND PROG.PROGRAM_TYPE_CODE=#{PROGRAM_TYPE_CODE}
AND PROG.USE_YN=#{USE_YN}
ORDER BY PROG.MODULE_CODE, PROG.PROGRAM_ID
